-- GASP conformance case c01_cohort_nrr: a cohort fixed at the opening of the period and followed through its events (Net Revenue Retention).
-- Metric gasp_nrr (GASP formula: (metric.mrr at period_start + metric.expansion_mrr - metric.contraction_mrr - metric.churned_mrr) / metric.mrr at period_start over cohort(field.customer_id, period_start)) for the period 2026-01-01 to 2026-06-30.
-- The select list is the metric's OSSIE_SQL_2026 expression, evaluated over the rows of the period.
-- The subquery is the source of the staged dataset gasp_account_cohorts in model.ossie.yaml,
-- one row per cohort member per period, compiled by GASP from the formula (Postgres dialect; the GASP extension on the dataset carries
-- Snowflake, BigQuery and Databricks). It reads the tables in ../../data/, including gasp.period_spine.
SELECT (CAST((((SUM(gasp_account_cohorts.opening_mrr) + SUM(gasp_account_cohorts.expansion_mrr)) - SUM(gasp_account_cohorts.contraction_mrr)) - SUM(gasp_account_cohorts.churned_mrr)) AS DECIMAL) / NULLIF(SUM(gasp_account_cohorts.opening_mrr), 0)) AS value
FROM (SELECT p.period_start, p.period_end, _c.customer_id, (SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active' AND customer_id = _c.customer_id) AS opening_mrr, (SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'expansion' AND customer_id = _c.customer_id) AS expansion_mrr, (-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction' AND customer_id = _c.customer_id)) AS contraction_mrr, (-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn' AND customer_id = _c.customer_id)) AS churned_mrr FROM gasp.period_spine p JOIN (SELECT customer_id AS customer_id, snapshot_date AS _day FROM gasp.customer WHERE customer_status = 'active') _c ON _c._day = p.period_start) AS gasp_account_cohorts
WHERE period_start = DATE '2026-01-01' AND period_end = DATE '2026-06-30';
